<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Outbox\Domain\Model;

/**
 * Domain model representing an outbound email ready to be sent.
 */
class OutboundMail
{
    public function __construct(
        private readonly string $recipient,
        private readonly string $htmlContent,
        private readonly string $subject = '',
        private readonly ?string $textContent = null,
    ) {
    }

    /** Destination email address where the message will be delivered. */
    public function recipient(): string
    {
        return $this->recipient;
    }

    /** Email subject line. */
    public function subject(): string
    {
        return $this->subject;
    }

    /** HTML body of the message. Always present. */
    public function htmlContent(): string
    {
        return $this->htmlContent;
    }

    /** Plain-text alternative body. Null when the template does not define a text variant. */
    public function textContent(): ?string
    {
        return $this->textContent;
    }
}
